SELECT * FROM ads_order_analysis
WHERE dimension_type = #{dimensionType}

    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY stat_date ASC, dimension_value ASC

SELECT * FROM ads_order_analysis
WHERE dimension_type IN

    #{t}


    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY stat_date ASC, dimension_type ASC, dimension_value ASC

SELECT * FROM ads_order_analysis
WHERE dimension_type = #{dimensionType}

    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY ${orderField} DESC
LIMIT #{limit}

SELECT dimension_value AS dimensionValue, SUM(order_count) AS orderCount, SUM(paid_order_count) AS paidOrderCount, SUM(total_amount) AS totalAmount FROM ads_order_analysis WHERE dimension_type = 'hour'
AND stat_date >= #{startDate}
AND stat_date <= #{endDate}
GROUP BY dimension_value ORDER BY dimension_value ASC
